import{_ as a,C as r,o,c as n,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Durable Agent Approval Needs an Occurrence Boundary","description":"","frontmatter":{"title":"Durable Agent Approval Needs an Occurrence Boundary","date":"2026-08-16","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How should a durable agent runtime represent one human decision for one concrete tool-call occurrence when a broader sticky authorization default already exists?","summary":"Durable approval is safer when a broad policy default and a narrow occurrence-scoped exception are persisted as different facts. Exact call identity can preserve one decision across resume, but it does not establish approver identity, policy provenance, or exactly-once external effects.","sources":["research/analysis/Q-20260816-01-occurrence-scoped-authorization-state.md"],"item_id":"Q-20260816-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-16-occurrence-scoped-authorization-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-16-occurrence-scoped-authorization.md","filePath":"en/digital-employee/2026-08-16-occurrence-scoped-authorization.md","lastUpdated":1786882274000}'),c={name:"en/digital-employee/2026-08-16-occurrence-scoped-authorization.md"};function l(d,e,h,p,u,f){const t=r("ArticleCover");return o(),n("div",null,[i(t,{image:"/assets/covers/daily-2026-08-16-occurrence-scoped-authorization-cover.png",kicker:"Digital Employee · Daily Research",title:"Durable Agent Approval Needs an Occurrence Boundary",summary:"Durable approval is safer when a broad policy default and a narrow occurrence-scoped exception are persisted as different facts. Exact call identity can preserve one decision across resume, but it does not establish approver identity, policy provenance, or exactly-once external effects.",version:"Q-20260816-01",status:"Daily Runtime V5 · 2026-08-16",languageHref:"/zh/digital-employee/2026-08-16-occurrence-scoped-authorization",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="durable-agent-approval-needs-an-occurrence-boundary" tabindex="-1">Durable Agent Approval Needs an Occurrence Boundary <a class="header-anchor" href="#durable-agent-approval-needs-an-occurrence-boundary" aria-label="Permalink to &quot;Durable Agent Approval Needs an Occurrence Boundary&quot;">​</a></h1><p>A durable agent can pause on a tool call, wait for a human decision, serialize its state, restart, and later continue. That continuity creates a deceptively simple question: what exactly did the human authorize?</p><p>A broad tool-level rule and a one-time exception are not the same fact. If a user approves one concrete invocation while a sticky default still rejects other calls of the same tool, changing the default would silently widen the human decision. A more precise model keeps the broad rule intact and records a narrow exception against the exact pending occurrence.</p><p>The 2026-08-16 Research Object examined a merged OpenAI Agents Python change in which exact approved or rejected call IDs are resolved before sticky defaults. Regression and serialization evidence show that an exact exception can survive resume together with the broader default, and that reversing an exact decision removes the opposite exact record rather than accumulating contradictory state. The evidence is bounded implementation evidence from maintainer code and tests; it is not an independent evaluation of enterprise authorization.</p><h2 id="a-durable-decision-needs-a-narrow-object" tabindex="-1">A durable decision needs a narrow object <a class="header-anchor" href="#a-durable-decision-needs-a-narrow-object" aria-label="Permalink to &quot;A durable decision needs a narrow object&quot;">​</a></h2><p>The first architectural benefit of occurrence-scoped state is scope control. A sticky policy such as “approve this tool” or “reject this tool” is intentionally reusable. An exact-call exception has a different meaning: “for this recorded occurrence, use this decision.”</p><p>That distinction matters most during recovery. If the exception disappears after restart, the resumed system may fall back to a broader rule and change the effective authorization. If the system rewrites the broad rule to preserve one exception, it may unintentionally affect sibling calls. Persisting both layers avoids those two failure modes.</p><p>The selected implementation also handles reversal explicitly. When an exact call changes from approved to rejected, or the reverse, the opposite exact entry is removed. This is a useful state invariant: one occurrence should not carry two contradictory terminal decisions at once.</p><p>But the exact call ID answers only one question: <strong>which invocation is this decision about?</strong> It does not establish who made the decision, whether that actor had authority, whether the call identifier is cryptographically trustworthy across trust domains, or whether the external effect happened exactly once.</p><h2 id="separate-the-decision-from-the-actor-and-the-effect" tabindex="-1">Separate the decision from the actor and the effect <a class="header-anchor" href="#separate-the-decision-from-the-actor-and-the-effect" aria-label="Permalink to &quot;Separate the decision from the actor and the effect&quot;">​</a></h2><p>For durable digital work, authorization is stronger when four facts remain separable:</p><p><strong>default policy → occurrence-scoped decision → actor/authority evidence → external-effect evidence</strong>.</p><p>The default policy defines the reusable rule. The occurrence-scoped decision records a bounded exception for a concrete pending action. Actor and authority evidence explain who supplied that exception and under which policy or role. External-effect evidence records what actually happened after authorization.</p><p>These layers have different lifetimes and different proof requirements. A persisted approval can remain valid across a restart while the identity provider that authenticated the approver lives outside the agent SDK. Likewise, a correct authorization record does not prove that a payment, message, deployment, or other external side effect was executed exactly once.</p><p>This separation also makes audit records easier to interpret. “Approval restored from state” should not be conflated with “approver identity verified” or “effect completed.” A governance system can record all three, but it should not infer one from another.</p><p>For higher-risk tools, a durable exception should also be bound to an action fingerprint that can be rechecked on resume. Tool identity, arguments, tool version, and governing policy are plausible fingerprint inputs. If a material part changes, the safer behavior is to invalidate or re-admit the exception rather than replay an old decision onto changed work. That is an architectural interpretation from the Research Object, not a behavior established by the selected SDK patch.</p><h2 id="what-this-mechanism-does-not-establish" tabindex="-1">What this mechanism does not establish <a class="header-anchor" href="#what-this-mechanism-does-not-establish" aria-label="Permalink to &quot;What this mechanism does not establish&quot;">​</a></h2><p>The implementation evidence does not authenticate the approver. It does not establish role policy, cryptographic provenance, globally unique or unforgeable call identifiers, or finality of external effects. It also does not show that occurrence-scoped approval is the right complexity level for every workload.</p><p>A low-risk single-user agent may reasonably let the surrounding application own identity and authorization. In a tightly controlled environment, a stable call ID plus a durable exact decision may be sufficient if the tool arguments and policy cannot change between pause and resume.</p><p>The architectural lesson is therefore not “every agent must implement a full authorization stack.” It is narrower: <strong>do not let one durable decision silently stand in for several different kinds of evidence</strong>.</p><h2 id="open-questions-for-high-risk-resumable-actions" tabindex="-1">Open questions for high-risk resumable actions <a class="header-anchor" href="#open-questions-for-high-risk-resumable-actions" aria-label="Permalink to &quot;Open questions for high-risk resumable actions&quot;">​</a></h2><p>What actor, role, and policy evidence should be persisted beside a high-risk exact-call decision? Which fields should be immutable in an action fingerprint? How should an imported state prove that occurrence identifiers and approval records were not forged or replayed across trust domains?</p><p>Durability makes a decision resumable. It does not automatically make that decision authentic, authorized, or final. The occurrence boundary is the right place to preserve scope; the rest of the trust chain still needs its own evidence.</p>',23))])}const b=a(c,[["render",l]]);export{y as __pageData,b as default};
